    public static AnimationDefinition byName(String name) { return switch(name) {
        case "walk" -> WALK;
        case "run" -> RUN;
        case "idle_breathe" -> IDLE_BREATHE;
        case "down_hold" -> DOWN_HOLD;
        default -> throw new IllegalArgumentException("Unknown mouse clip: " + name);
    }; }
